{
  "modelPrompt": {
    "subject_definitions": "<Subject 1>: golden coin with cat face relief, appearance from <Picture 1>",
    "summary": "[video editing + reference generation] The target video is an edited version of <Video 1>. The original coins are replaced by <Subject 1> while retaining the original motion, timing, camera, framing and green screen background.",
    "retention_analysis": "<Video 1>: partially_preserved - motion, timing, camera, framing and green screen background retained; original coin appearance replaced throughout.\n<Subject 1>: attribute_transfer - cat face coin appearance applied to all coin instances.",
    "detailed_description": "Retain the reference appearance. [Shot 1] Golden coins bearing the cat face design from <Subject 1> appear in the exact positions, sizes, trajectories and rotation phases shown in <Video 1>, flipping and turning edge-on against the solid green screen over the full 3-second duration.",
    "overall_soundscape": "Silent, no diegetic sounds present.",
    "non_diegetic_music": "None."
  },
  "displayPrompt": {
    "subject_definitions": "<Subject 1>: 带有猫脸浮雕的金币，外观来自 <Picture 1>",
    "summary": "[video editing + reference generation] 目标视频是 <Video 1> 的编辑版本。原金币被替换为 <Subject 1>，同时保留原有运动、时序、机位、构图和绿幕背景。",
    "retention_analysis": "<Video 1>: partially_preserved - 保留运动、时序、机位、构图和绿幕背景；全程替换原有金币外观。\n<Subject 1>: attribute_transfer - 猫脸金币外观应用于所有金币实例。",
    "detailed_description": "保留参考外观。[Shot 1] 带有 <Subject 1> 猫脸图案的金币以 <Video 1> 中所示的精确位置、大小、轨迹和旋转阶段出现，在纯绿幕背景下翻转并转至侧面，持续完整3秒。",
    "overall_soundscape": "无声，无拟音存在。",
    "non_diegetic_music": "无。"
  }
}
